import { readFileSync } from "node:fs";
import { isPackedIdSet, unpackIds } from "@unbored/contracts/packed";
import { professionSkills } from "@unbored/contracts/skill-route";
import type {
  CharacterEvent,
  CharacterEventType,
  HistoryFilter,
  HistoryPage,
} from "@unbored/contracts/character-history";
import type { Db, Param } from "./db.ts";

export const EVENTS_SQLITE_SCHEMA = readFileSync(
  new URL("../migrations/0032_character_events.sql", import.meta.url),
  "utf8",
)
  .split("-- PostgreSQL-only permissions:")[0]!
  .replace(
    "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
    "INTEGER PRIMARY KEY AUTOINCREMENT",
  )
  .replaceAll("CREATE TABLE ", "CREATE TABLE IF NOT EXISTS ")
  .replaceAll("CREATE UNIQUE INDEX ", "CREATE UNIQUE INDEX IF NOT EXISTS ")
  .replaceAll("CREATE INDEX ", "CREATE INDEX IF NOT EXISTS ");
export const EVENT_SECTIONS = ["char", "professions", "recipes", "gear", "reputation"];
type Event = Omit<CharacterEvent, "id">;
type Raw = Record<string, unknown>;
const record = (v: unknown): Raw =>
  v && typeof v === "object" && !Array.isArray(v) ? (v as Raw) : {};
const number = (v: unknown): number | null =>
  typeof v === "number" && Number.isSafeInteger(v) && v >= 0 ? v : null;
const list = (v: unknown): Raw[] => (Array.isArray(v) ? v.map(record) : []);
function recipes(body: Raw): Set<number> {
  return new Set(
    Object.values(record(body.byProfession)).flatMap((value) => {
      const learned = record(value).learned;
      return isPackedIdSet(learned) ? unpackIds(learned) : [];
    }),
  );
}

/** Missing fields are unknown; a first Section is a baseline, apart from chart points. */
export function deriveCharacterEvents(
  section: string,
  before: Raw | null,
  after: Raw,
  at: number,
): Event[] {
  const out: Event[] = [];
  const add = (type: CharacterEventType, key: string, from: number | null, to: number | null) => {
    if (to !== null) out.push({ type, key, at, from, to });
  };
  if (section === "char") {
    const old = number(before?.level),
      level = number(after.level);
    if (level !== null && (before === null || (old !== null && level > old)))
      add("level_up", "", old, level);
    add("gold_close", "", null, number(after.money));
  }
  if (!before) return out;
  if (section === "professions") {
    const old = new Map(professionSkills(before).map((p) => [p.skillLine, p.skill]));
    for (const p of professionSkills(after)) {
      const from = old.get(p.skillLine) ?? null;
      if (from !== null && p.skill !== null && from !== p.skill)
        add("skill_step", String(p.skillLine), from, p.skill);
    }
  }
  if (section === "recipes") {
    const old = recipes(before);
    for (const id of recipes(after)) if (!old.has(id)) add("recipe_learned", String(id), null, id);
  }
  if (section === "gear" && Array.isArray(before.slots) && Array.isArray(after.slots)) {
    const old = new Map(list(before.slots).map((r) => [number(r.slot), number(r.itemID)]));
    const fresh = new Map(list(after.slots).map((r) => [number(r.slot), number(r.itemID)]));
    for (const slot of new Set([...old.keys(), ...fresh.keys()])) {
      if (slot === null) continue;
      if (
        (old.has(slot) && old.get(slot) === null) ||
        (fresh.has(slot) && fresh.get(slot) === null)
      )
        continue;
      const from = old.get(slot) ?? 0,
        to = fresh.get(slot) ?? 0;
      if (from !== to) add("gear_change", String(slot), from, to);
    }
  }
  if (section === "reputation") {
    const old = new Map(
      list(before.factions).map((r) => [number(r.factionID), number(r.reaction)]),
    );
    for (const r of list(after.factions)) {
      const id = number(r.factionID),
        from = old.get(id) ?? null,
        to = number(r.reaction);
      if (id !== null && from !== null && to !== null && from !== to)
        add("rep_standing", String(id), from, to);
    }
  }
  return out;
}

/** Legacy packed history contains additions, not full recipe sets. Never invent capped ids. */
export function recipeHistoryEvents(body: unknown, at: number): Event[] {
  const ids = record(record(body).ids);
  const added = new Set<number>();
  for (const [key, value] of Object.entries(ids)) {
    if (!/^byProfession\.\d+\.learned$/.test(key)) continue;
    const rows = record(value).added;
    for (const id of Array.isArray(rows) ? rows : [])
      if (number(id) !== null) added.add(id as number);
  }
  return [...added].map((id) => ({
    type: "recipe_learned",
    key: String(id),
    at,
    from: null,
    to: id,
  }));
}

export async function writeCharacterEvents(
  db: Db,
  game: string,
  character: string,
  events: Event[],
): Promise<void> {
  // Bounded multi-row writes avoid a round trip per learned recipe on backfill.
  for (let start = 0; start < events.length; start += 100) {
    const rows = events.slice(start, start + 100);
    for (const gold of [false, true]) {
      const selected = rows.filter((e) => (e.type === "gold_close") === gold);
      // A batch may contain several closes on one day; only its last source timestamp wins.
      const unique = new Map<string, Event>();
      for (const e of selected) {
        const key = gold ? String(Math.floor(e.at / 86400)) : `${e.type}:${e.key}:${e.at}`;
        if (!unique.has(key) || unique.get(key)!.at <= e.at) unique.set(key, e);
      }
      if (!unique.size) continue;
      const values = [...unique.values()];
      await db.run(
        `INSERT INTO character_events (game, character_id, type, key, at, from_value, to_value, day)
        VALUES ${values.map(() => "(?, ?, ?, ?, ?, ?, ?, ?)").join(",")}
        ${gold ? `ON CONFLICT (character_id, day) WHERE type = 'gold_close' DO UPDATE SET at = excluded.at, to_value = excluded.to_value WHERE excluded.at > character_events.at` : "ON CONFLICT (character_id, type, key, at) DO NOTHING"}`,
        ...values.flatMap((e) => [
          game,
          character,
          e.type,
          e.key,
          e.at,
          e.from === null ? null : String(e.from),
          String(e.to),
          gold ? Math.floor(e.at / 86400) : null,
        ]),
      );
    }
  }
}

export async function readCharacterHistory(
  db: Db,
  owner: { accountId: string; game: string; characterId: string },
  filter: HistoryFilter = {},
): Promise<HistoryPage> {
  const where = ["c.account_id = ?", "c.game = ?", "e.game = c.game", "e.character_id = ?"];
  const args: Param[] = [owner.accountId, owner.game, owner.characterId];
  if (filter.types?.length) {
    where.push(`e.type IN (${filter.types.map(() => "?").join(",")})`);
    args.push(...filter.types);
  }
  if (filter.since !== undefined) {
    where.push("e.at >= ?");
    args.push(filter.since);
  }
  if (filter.cursor) {
    where.push("(e.at < ? OR (e.at = ? AND e.id < ?))");
    args.push(filter.cursor.at, filter.cursor.at, filter.cursor.id);
  }
  const limit = Math.max(1, Math.min(100, filter.limit ?? 100));
  const rows = await db.all<{
    id: number;
    type: CharacterEventType;
    key: string;
    at: number;
    from_value: string | null;
    to_value: string;
  }>(
    `SELECT e.* FROM character_events e JOIN characters c ON c.id = e.character_id WHERE ${where.join(" AND ")} ORDER BY e.at DESC, e.id DESC LIMIT ?`,
    ...args,
    limit + 1,
  );
  const events = rows.slice(0, limit).map((r) => ({
    id: r.id,
    type: r.type,
    key: r.key,
    at: r.at,
    from: r.from_value === null ? null : Number(r.from_value),
    to: Number(r.to_value),
  }));
  const last = events.at(-1);
  return { events, next: rows.length > limit && last ? { at: last.at, id: last.id } : null };
}
